    'campaigns.chatWelcome1': 'Discutons de ta prochaine campagne. Pas besoin de tout dire d\'un coup, on avance question par question, et à la fin je te propose un récapitulatif que tu pourras valider ou corriger. Un conseil : plus tes réponses sont détaillées, mieux je comprends ta stratégie commerciale et plus mes questions et recommandations seront pertinentes.',
