    'tour.slide.dashboard.title': 'Tableau de bord',
    'tour.slide.dashboard.text': 'Ta vue d\'ensemble : prospects chauds, prochains RDV, et le bloc "Actions requises" où tu valides ce qu\'Aaron a préparé pour toi.',
    'tour.slide.prospects.title': 'Prospects',
    'tour.slide.prospects.text': 'Le pipeline complet, avec une couleur par statut : vert (en bonne voie), jaune (en cours), orange (risque de perdre), rouge (perdu), bleu (RDV obtenu). Astuce pour découvrir Aaron sans risque : crée ici un prospect test à la main avec une variante de ta propre adresse email (ex: prenom+test1@gmail.com, +test2… — Gmail les livre quand même dans ta boîte), regarde comment Aaron te répond, puis supprime-le et lance ta vraie campagne :)',
    'tour.slide.sales.title': 'Opportunités',
    'tour.slide.sales.text': 'Une fois un rendez-vous obtenu : devis chiffrés à partir de ton catalogue, conseils avant chaque RDV, relances jusqu\'à la signature — et l\'envoi en signature électronique pour clore l\'affaire.',
    'tour.slide.customer.title': 'Clients',
    'tour.slide.customer.text': 'Dès qu\'un client est gagné : onboarding automatique, suivi de sa santé, réponses aux demandes courantes, et alertes s\'il montre des signes de mécontentement.',
    'tour.slide.campaigns.title': 'Campagnes',
    'tour.slide.campaigns.text': 'Lance une prospection sur une zone géographique — Aaron cherche, contacte et négocie un RDV pour toi, sans que tu aies à écrire un seul email.',
    'tour.slide.agenda.title': 'Agenda',
    'tour.slide.agenda.text': 'Tous tes RDV proposés par Aaron, avec un calendrier mensuel. Tu valides, reportes ou annules en un clic, et tu déclares aussi tes créneaux habituels et tes indisponibilités — Aaron gère ton calendrier Google et évite les conflits automatiquement.',
    'tour.slide.resultats.title': 'Mes résultats',
    'tour.slide.resultats.text': 'Tes statistiques par catégorie (prospects, opportunités, clients), un historique de rapports téléchargeables, et l\'évolution de ta performance dans le temps — pour savoir ce qui marche vraiment.',
    'tour.slide.documents.title': 'Mes documents',
    'tour.slide.documents.text': 'Dépose un devis type, une plaquette, une liste de tarifs — Aaron les lit, les résume, et s\'en sert pour mieux te représenter auprès des prospects.',
    'tour.slide.chat.title': 'Chat avec Aaron',
    'tour.slide.chat.text': 'Pose tes questions, demande un conseil commercial. Toute suggestion sur l\'outil est automatiquement relayée au fondateur, sans email à écrire.',
    'tour.slide.connexions.title': 'Mon compte',
    'tour.slide.connexions.text': 'Tout est regroupé ici : ton profil, ton entreprise (ce qu\'Aaron a compris de ton métier), la connexion de ta boîte mail et de ton agenda (Google ou Microsoft), l\'annuaire des CRM, tes préférences de notification, et ton abonnement (modules actifs, crédits, factures).',
    'tour.slide.team.title': 'Mon équipe',
    'tour.slide.team.text': 'Vue d\'ensemble de chaque commercial : leurs statistiques et leur activité, en un coup d\'œil.',
    'tour.slide.suggestions.title': 'Suggestions',
    'tour.slide.suggestions.text': 'Les retours de ton équipe, qu\'ils soient signalés manuellement ou détectés automatiquement par Aaron dans une conversation.',
