    'tour.slide.dashboard.title': 'Dashboard',
    'tour.slide.dashboard.text': 'Your overview: hot prospects, upcoming appointments, and the "Action needed" block where you approve what Aaron has prepared for you.',
    'tour.slide.prospects.title': 'Prospects',
    'tour.slide.prospects.text': 'The full pipeline, color-coded by status: green (on track), yellow (in progress), orange (at risk of losing), red (lost), blue (appointment secured). Tip to try Aaron risk-free: create a test prospect here by hand using a variant of your own email address (e.g. firstname+test1@gmail.com, +test2… — Gmail still delivers them to your inbox), see how Aaron responds, then delete it and launch your real campaign :)',
    'tour.slide.sales.title': 'Opportunities',
    'tour.slide.sales.text': 'Once an appointment is booked: priced quotes from your catalog, advice before each meeting, follow-ups through to signature — and e-signature sending to close the deal.',
    'tour.slide.customer.title': 'Clients',
    'tour.slide.customer.text': 'As soon as a client is won: automatic onboarding, health tracking, replies to common requests, and alerts if a client shows signs of dissatisfaction.',
    'tour.slide.campaigns.title': 'Campaigns',
    'tour.slide.campaigns.text': 'Launch prospecting on a geographic area — Aaron searches, reaches out, and negotiates an appointment for you, without you writing a single email.',
    'tour.slide.agenda.title': 'Calendar',
    'tour.slide.agenda.text': 'All the appointments Aaron proposes, with a monthly calendar. Approve, reschedule, or cancel in one click, and set your usual time slots and unavailability too — Aaron manages your Google Calendar and avoids conflicts automatically.',
    'tour.slide.resultats.title': 'My results',
    'tour.slide.resultats.text': 'Your stats by category (prospects, opportunities, clients), a history of downloadable reports, and how your performance evolves over time — so you know what really works.',
    'tour.slide.documents.title': 'My documents',
    'tour.slide.documents.text': 'Upload a sample quote, a brochure, a price list — Aaron reads them, summarizes them, and uses them to better represent you to prospects.',
    'tour.slide.chat.title': 'Chat with Aaron',
    'tour.slide.chat.text': 'Ask your questions, request sales advice. Any suggestion about the tool is automatically forwarded to the founder, with no email to write.',
    'tour.slide.connexions.title': 'My account',
    'tour.slide.connexions.text': 'Your profile, connecting your inbox and calendar (Google or Microsoft), and the CRM directory you can link to Aaron.',
    'tour.slide.preferences.title': 'Preferences',
    'tour.slide.preferences.text': 'Three tabs: your company (what Aaron understood about your business), your notification preferences, and your subscription (active modules, credits, invoices).',
    'tour.slide.team.title': 'My team',
    'tour.slide.team.text': 'An overview of each salesperson: their statistics and activity, at a glance.',
    'tour.slide.suggestions.title': 'Suggestions',
    'tour.slide.suggestions.text': 'Feedback from your team, whether flagged manually or automatically detected by Aaron in a conversation.',
    'tour.previous': 'Previous',
