    'tour.slide.dashboard.title': 'Dashboard',
    'tour.slide.dashboard.text': 'Deine Übersicht: heiße Interessenten, anstehende Termine und der Block „Aktion erforderlich", in dem du bestätigst, was Aaron für dich vorbereitet hat.',
    'tour.slide.prospects.title': 'Interessenten',
    'tour.slide.prospects.text': 'Die vollständige Pipeline, farblich nach Status: grün (auf gutem Weg), gelb (in Bearbeitung), orange (Verlustrisiko), rot (verloren), blau (Termin vereinbart). Tipp, um Aaron risikofrei auszuprobieren: Lege hier von Hand einen Test-Interessenten mit einer Variante deiner eigenen E-Mail-Adresse an (z. B. vorname+test1@gmail.com, +test2… — Gmail liefert sie trotzdem in dein Postfach), schau dir an, wie Aaron antwortet, und lösche ihn danach, um deine echte Kampagne zu starten :)',
    'tour.slide.sales.title': 'Chancen',
    'tour.slide.sales.text': 'Sobald ein Termin vereinbart ist: kalkulierte Angebote aus deinem Katalog, Tipps vor jedem Termin, Nachfassen bis zur Unterschrift — und Versand zur elektronischen Signatur, um den Abschluss zu besiegeln.',
    'tour.slide.customer.title': 'Kunden',
    'tour.slide.customer.text': 'Sobald ein Kunde gewonnen ist: automatisches Onboarding, Gesundheits-Tracking, Antworten auf häufige Anfragen und Warnungen, wenn ein Kunde Anzeichen von Unzufriedenheit zeigt.',
    'tour.slide.campaigns.title': 'Kampagnen',
    'tour.slide.campaigns.text': 'Starte eine Akquise in einem geografischen Gebiet — Aaron sucht, kontaktiert und vereinbart einen Termin für dich, ohne dass du auch nur eine E-Mail schreiben musst.',
    'tour.slide.agenda.title': 'Kalender',
    'tour.slide.agenda.text': 'Alle von Aaron vorgeschlagenen Termine, mit einem Monatskalender. Bestätige, verschiebe oder storniere mit einem Klick und lege auch deine üblichen Zeitfenster und Abwesenheiten fest — Aaron verwaltet deinen Google-Kalender und vermeidet automatisch Terminkonflikte.',
    'tour.slide.resultats.title': 'Meine Ergebnisse',
    'tour.slide.resultats.text': 'Deine Statistiken nach Kategorie (Interessenten, Chancen, Kunden), ein Verlauf herunterladbarer Berichte und die Entwicklung deiner Leistung im Zeitverlauf — damit du weißt, was wirklich funktioniert.',
    'tour.slide.documents.title': 'Meine Dokumente',
    'tour.slide.documents.text': 'Lade ein Muster-Angebot, eine Broschüre oder eine Preisliste hoch — Aaron liest sie, fasst sie zusammen und nutzt sie, um dich gegenüber Interessenten besser zu vertreten.',
    'tour.slide.chat.title': 'Chat mit Aaron',
    'tour.slide.chat.text': 'Stelle deine Fragen, bitte um Verkaufsberatung. Jeder Vorschlag zum Tool wird automatisch an den Gründer weitergeleitet, ohne dass du eine E-Mail schreiben musst.',
    'tour.slide.connexions.title': 'Mein Konto',
    'tour.slide.connexions.text': 'Dein Profil, die Verbindung deines Postfachs und Kalenders (Google oder Microsoft) sowie das CRM-Verzeichnis, das du mit Aaron verknüpfen kannst.',
    'tour.slide.preferences.title': 'Einstellungen',
    'tour.slide.preferences.text': 'Drei Tabs: dein Unternehmen (was Aaron über dein Geschäft verstanden hat), deine Benachrichtigungseinstellungen und dein Abonnement (aktive Module, Guthaben, Rechnungen).',
    'tour.slide.team.title': 'Mein Team',
    'tour.slide.team.text': 'Übersicht über jeden Vertriebsmitarbeiter: seine Statistiken und Aktivitäten auf einen Blick.',
    'tour.slide.suggestions.title': 'Vorschläge',
    'tour.slide.suggestions.text': 'Das Feedback deines Teams, ob manuell gemeldet oder von Aaron automatisch in einem Gespräch erkannt.',
    'tour.previous': 'Zurück',
    'tour.next': 'Weiter',
