    'connexions.deleteIntro': 'Wenn Sie der einzige Nutzer dieses Meet Aaron-Arbeitsbereichs sind, werden alle Ihre Daten (Interessenten, Opportunities, Kunden, Kampagnen, Rechnungen...) endg\u00fcltig gel\u00f6scht und Ihr Abonnement gek\u00fcndigt. Wenn Sie Teil eines Teams sind, wird nur Ihr pers\u00f6nlicher Zugang entfernt \u2014 die Unternehmensdaten bleiben f\u00fcr Ihre Kollegen verf\u00fcgbar. Diese Aktion ist unwiderruflich und wird 24 Stunden nach Best\u00e4tigung wirksam.',
