    'tour.slide.dashboard.title': 'Dashboard',
    'tour.slide.dashboard.text': 'La tua panoramica: prospect caldi, i prossimi appuntamenti e il blocco "Azioni richieste" dove convalidi ciò che Aaron ha preparato per te.',
    'tour.slide.prospects.title': 'Prospect',
    'tour.slide.prospects.text': 'L\'intera pipeline, con un colore per ogni stato: verde (in buona strada), giallo (in corso), arancione (rischio di perdita), rosso (perso), blu (appuntamento ottenuto). Consiglio per provare Aaron senza rischi: crea qui manualmente un prospect di prova con una variante del tuo indirizzo email (es. nome+test1@gmail.com, +test2… — Gmail li consegna comunque nella tua casella), guarda come risponde Aaron, poi eliminalo e avvia la tua vera campagna :)',
    'tour.slide.sales.title': 'Opportunità',
    'tour.slide.sales.text': 'Una volta ottenuto un appuntamento: preventivi calcolati dal tuo catalogo, consigli prima di ogni appuntamento, solleciti fino alla firma — e invio per la firma elettronica per chiudere la trattativa.',
    'tour.slide.customer.title': 'Clienti',
    'tour.slide.customer.text': 'Non appena un cliente è acquisito: onboarding automatico, monitoraggio della salute del cliente, risposte alle richieste comuni e avvisi se un cliente mostra segni di insoddisfazione.',
    'tour.slide.campaigns.title': 'Campagne',
    'tour.slide.campaigns.text': 'Avvia una prospezione su una zona geografica — Aaron cerca, contatta e negozia un appuntamento per te, senza che tu debba scrivere una sola email.',
    'tour.slide.agenda.title': 'Agenda',
    'tour.slide.agenda.text': 'Tutti gli appuntamenti proposti da Aaron, con un calendario mensile. Convalidi, rimandi o annulli con un clic, e indichi anche le tue fasce orarie abituali e le tue indisponibilità — Aaron gestisce il tuo calendario Google ed evita automaticamente i conflitti.',
    'tour.slide.resultats.title': 'I miei risultati',
    'tour.slide.resultats.text': 'Le tue statistiche per categoria (prospect, opportunità, clienti), uno storico di report scaricabili e l\'andamento delle tue performance nel tempo — per sapere cosa funziona davvero.',
    'tour.slide.documents.title': 'I miei documenti',
    'tour.slide.documents.text': 'Carica un preventivo tipo, una brochure, un listino prezzi — Aaron li legge, li riassume e li usa per rappresentarti meglio presso i prospect.',
    'tour.slide.chat.title': 'Chat con Aaron',
    'tour.slide.chat.text': 'Fai le tue domande, chiedi un consiglio commerciale. Ogni suggerimento sullo strumento viene automaticamente inoltrato al fondatore, senza dover scrivere un\'email.',
    'tour.slide.connexions.title': 'Il mio account',
    'tour.slide.connexions.text': 'Il tuo profilo, il collegamento della tua casella di posta e del tuo calendario (Google o Microsoft), e la rubrica dei CRM che puoi collegare ad Aaron.',
    'tour.slide.preferences.title': 'Preferenze',
    'tour.slide.preferences.text': 'Tre schede: la tua azienda (ciò che Aaron ha capito del tuo lavoro), le tue preferenze di notifica e il tuo abbonamento (moduli attivi, crediti, fatture).',
    'tour.slide.team.title': 'Il mio team',
    'tour.slide.team.text': 'Panoramica di ogni commerciale: le sue statistiche e la sua attività, a colpo d\'occhio.',
    'tour.slide.suggestions.title': 'Suggerimenti',
    'tour.slide.suggestions.text': 'I feedback del tuo team, siano essi segnalati manualmente o rilevati automaticamente da Aaron in una conversazione.',
