    'tour.slide.dashboard.title': 'Panel de control',
    'tour.slide.dashboard.text': 'Tu visión general: prospectos en caliente, próximas citas y el bloque "Acciones requeridas" donde validas lo que Aaron ha preparado para ti.',
    'tour.slide.prospects.title': 'Prospectos',
    'tour.slide.prospects.text': 'El pipeline completo, con un color por estado: verde (en buen camino), amarillo (en curso), naranja (riesgo de pérdida), rojo (perdido), azul (cita conseguida). Consejo para probar a Aaron sin riesgo: crea aquí a mano un prospecto de prueba con una variante de tu propio correo (ej. nombre+test1@gmail.com, +test2… — Gmail los entrega igualmente en tu bandeja), mira cómo responde Aaron, y luego elimínalo y lanza tu campaña real :)',
    'tour.slide.sales.title': 'Oportunidades',
    'tour.slide.sales.text': 'En cuanto se consigue una cita: presupuestos calculados a partir de tu catálogo, consejos antes de cada cita, seguimientos hasta la firma — y envío para firma electrónica para cerrar el trato.',
    'tour.slide.customer.title': 'Clientes',
    'tour.slide.customer.text': 'En cuanto se gana un cliente: incorporación automática, seguimiento de su estado, respuestas a solicitudes habituales y alertas si un cliente muestra señales de insatisfacción.',
    'tour.slide.campaigns.title': 'Campañas',
    'tour.slide.campaigns.text': 'Lanza una prospección en una zona geográfica — Aaron busca, contacta y negocia una cita por ti, sin que tengas que escribir un solo correo.',
    'tour.slide.agenda.title': 'Agenda',
    'tour.slide.agenda.text': 'Todas las citas propuestas por Aaron, con un calendario mensual. Confirma, pospón o cancela con un clic, e indica también tus franjas horarias habituales y tus indisponibilidades — Aaron gestiona tu calendario de Google y evita los conflictos automáticamente.',
    'tour.slide.resultats.title': 'Mis resultados',
    'tour.slide.resultats.text': 'Tus estadísticas por categoría (prospectos, oportunidades, clientes), un historial de informes descargables y la evolución de tu rendimiento en el tiempo — para saber qué funciona realmente.',
    'tour.slide.documents.title': 'Mis documentos',
    'tour.slide.documents.text': 'Sube un presupuesto tipo, un folleto, una lista de precios — Aaron los lee, los resume y los utiliza para representarte mejor ante los prospectos.',
    'tour.slide.chat.title': 'Chat con Aaron',
    'tour.slide.chat.text': 'Haz tus preguntas, pide un consejo comercial. Cualquier sugerencia sobre la herramienta se reenvía automáticamente al fundador, sin tener que escribir un correo.',
    'tour.slide.connexions.title': 'Mi cuenta',
    'tour.slide.connexions.text': 'Tu perfil, la conexión de tu correo y tu calendario (Google o Microsoft), y el directorio de CRM que puedes vincular a Aaron.',
    'tour.slide.preferences.title': 'Preferencias',
    'tour.slide.preferences.text': 'Tres pestañas: tu empresa (lo que Aaron ha entendido de tu negocio), tus preferencias de notificación y tu suscripción (módulos activos, créditos, facturas).',
    'tour.slide.team.title': 'Mi equipo',
    'tour.slide.team.text': 'Vista general de cada comercial: sus estadísticas y su actividad, de un vistazo.',
    'tour.slide.suggestions.title': 'Sugerencias',
    'tour.slide.suggestions.text': 'Los comentarios de tu equipo, ya sea que se hayan señalado manualmente o que Aaron los haya detectado automáticamente en una conversación.',
