    'tour.slide.dashboard.title': 'Painel',
    'tour.slide.dashboard.text': 'A tua visão geral: prospetos quentes, próximas reuniões e o bloco "Ações necessárias" onde validas o que o Aaron preparou para ti.',
    'tour.slide.prospects.title': 'Prospetos',
    'tour.slide.prospects.text': 'O pipeline completo, com uma cor por estado: verde (no bom caminho), amarelo (em curso), laranja (risco de perder), vermelho (perdido), azul (reunião obtida). Dica para experimentar o Aaron sem risco: cria aqui manualmente um prospeto de teste com uma variante do teu próprio email (ex: nome+test1@gmail.com, +test2… — o Gmail entrega-os na mesma na tua caixa), vê como o Aaron responde, depois elimina-o e lança a tua campanha real :)',
    'tour.slide.sales.title': 'Oportunidades',
    'tour.slide.sales.text': 'Assim que uma reunião é marcada: orçamentos calculados a partir do teu catálogo, conselhos antes de cada reunião, acompanhamentos até à assinatura — e envio para assinatura eletrónica para fechar o negócio.',
    'tour.slide.customer.title': 'Clientes',
    'tour.slide.customer.text': 'Assim que um cliente é conquistado: onboarding automático, acompanhamento da saúde do cliente, respostas a pedidos comuns e alertas se um cliente mostrar sinais de insatisfação.',
    'tour.slide.campaigns.title': 'Campanhas',
    'tour.slide.campaigns.text': 'Lança uma prospeção numa zona geográfica — o Aaron procura, contacta e negoceia uma reunião por ti, sem teres de escrever um único email.',
    'tour.slide.agenda.title': 'Agenda',
    'tour.slide.agenda.text': 'Todas as reuniões propostas pelo Aaron, com um calendário mensal. Confirmas, remarcas ou cancelas com um clique, e indicas também os teus horários habituais e as tuas indisponibilidades — o Aaron gere o teu calendário do Google e evita conflitos automaticamente.',
    'tour.slide.resultats.title': 'Meus resultados',
    'tour.slide.resultats.text': 'As tuas estatísticas por categoria (prospetos, oportunidades, clientes), um histórico de relatórios descarregáveis e a evolução do teu desempenho ao longo do tempo — para saberes o que realmente funciona.',
    'tour.slide.documents.title': 'Os meus documentos',
    'tour.slide.documents.text': 'Carrega um orçamento tipo, um folheto, uma lista de preços — o Aaron lê-os, resume-os e usa-os para te representar melhor junto dos prospetos.',
    'tour.slide.chat.title': 'Chat com o Aaron',
    'tour.slide.chat.text': 'Faz as tuas perguntas, pede um conselho comercial. Qualquer sugestão sobre a ferramenta é automaticamente reencaminhada para o fundador, sem teres de escrever um email.',
    'tour.slide.connexions.title': 'Minha conta',
    'tour.slide.connexions.text': 'O teu perfil, a ligação da tua caixa de email e da tua agenda (Google ou Microsoft), e o diretório de CRM que podes ligar ao Aaron.',
    'tour.slide.preferences.title': 'Preferências',
    'tour.slide.preferences.text': 'Três separadores: a tua empresa (o que o Aaron percebeu do teu negócio), as tuas preferências de notificação e a tua subscrição (módulos ativos, créditos, faturas).',
    'tour.slide.team.title': 'A minha equipa',
    'tour.slide.team.text': 'Visão geral de cada comercial: as suas estatísticas e a sua atividade, num relance.',
    'tour.slide.suggestions.title': 'Sugestões',
    'tour.slide.suggestions.text': 'O feedback da tua equipa, quer seja assinalado manualmente ou detetado automaticamente pelo Aaron numa conversa.',
    'tour.previous': 'Anterior',
    'tour.next': 'Seguinte',
