    'tour.slide.dashboard.title': 'Dashboard',
    'tour.slide.dashboard.text': 'Je overzicht: hete prospects, aankomende afspraken en het blok "Actie vereist" waar je goedkeurt wat Aaron voor je heeft voorbereid.',
    'tour.slide.prospects.title': 'Prospects',
    'tour.slide.prospects.text': 'De volledige pipeline, met een kleur per status: groen (op koers), geel (in behandeling), oranje (risico op verlies), rood (verloren), blauw (afspraak binnen). Tip om Aaron risicoloos uit te proberen: maak hier handmatig een testprospect aan met een variant van je eigen e-mailadres (bijv. voornaam+test1@gmail.com, +test2… — Gmail levert ze toch in je inbox af), bekijk hoe Aaron reageert, en verwijder hem daarna om je echte campagne te starten :)',
    'tour.slide.sales.title': 'Kansen',
    'tour.slide.sales.text': 'Zodra een afspraak is geboekt: berekende offertes uit je catalogus, advies vóór elke afspraak, opvolging tot aan de ondertekening — en verzending voor elektronische handtekening om de deal te sluiten.',
    'tour.slide.customer.title': 'Klanten',
    'tour.slide.customer.text': 'Zodra een klant is binnengehaald: automatische onboarding, opvolging van klantgezondheid, antwoorden op veelvoorkomende vragen en waarschuwingen als een klant tekenen van ontevredenheid vertoont.',
    'tour.slide.campaigns.title': 'Campagnes',
    'tour.slide.campaigns.text': 'Start prospectie in een geografisch gebied — Aaron zoekt, neemt contact op en onderhandelt een afspraak voor je, zonder dat je ook maar één e-mail hoeft te schrijven.',
    'tour.slide.agenda.title': 'Agenda',
    'tour.slide.agenda.text': 'Alle afspraken die Aaron voorstelt, met een maandkalender. Bevestig, verzet of annuleer met één klik, en geef ook je gebruikelijke tijdslots en afwezigheden op — Aaron beheert je Google-agenda en voorkomt conflicten automatisch.',
    'tour.slide.resultats.title': 'Mijn resultaten',
    'tour.slide.resultats.text': 'Je statistieken per categorie (prospects, kansen, klanten), een geschiedenis van downloadbare rapporten en de evolutie van je prestaties in de tijd — zo weet je wat écht werkt.',
    'tour.slide.documents.title': 'Mijn documenten',
    'tour.slide.documents.text': 'Upload een voorbeeldofferte, een brochure, een prijslijst — Aaron leest ze, vat ze samen en gebruikt ze om je beter te vertegenwoordigen bij prospects.',
    'tour.slide.chat.title': 'Chat met Aaron',
    'tour.slide.chat.text': 'Stel je vragen, vraag om verkoopadvies. Elke suggestie over de tool wordt automatisch doorgestuurd naar de oprichter, zonder dat je een e-mail hoeft te schrijven.',
    'tour.slide.connexions.title': 'Mijn account',
    'tour.slide.connexions.text': 'Je profiel, de koppeling van je mailbox en agenda (Google of Microsoft), en de CRM-directory die je met Aaron kunt koppelen.',
    'tour.slide.preferences.title': 'Voorkeuren',
    'tour.slide.preferences.text': 'Drie tabbladen: je bedrijf (wat Aaron over je vak heeft begrepen), je meldingsvoorkeuren en je abonnement (actieve modules, credits, facturen).',
    'tour.slide.team.title': 'Mijn team',
    'tour.slide.team.text': 'Overzicht van elke verkoper: hun statistieken en activiteit, in één oogopslag.',
    'tour.slide.suggestions.title': 'Suggesties',
    'tour.slide.suggestions.text': 'Feedback van je team, of die nu handmatig is gemeld of automatisch door Aaron in een gesprek is gedetecteerd.',
    'tour.previous': 'Vorige',
    'tour.next': 'Volgende',
    'tour.finish': 'Laten we beginnen!',
